GPT 5.6 Sol Ultra on Codex

LoadPackage("TomLib");;

tbl := CharacterTable("U3(5)");;
tom := TableOfMarks("U3(5)");;
irr := Irr(tbl);;

# Representatives of the 12 Galois orbits
reps := Concatenation([1..11], [13]);;
perms := PermCharsTom(tbl, tom);;

A := List(perms,
          pi -> List(reps, i -> ScalarProduct(irr[i], pi)));

e := ListWithIdenticalEntries(12, 0);;
e[12] := 1;;

snf := SmithNormalFormIntegerMatTransforms(A);;
diag := List([1..12], i -> snf.normal[i][i]);;
y := e * snf.coltrans;;

Print(Size(tbl), " ", irr[13][1], "\n");
Print(diag, "\n", y, "\n");
Print(SolutionIntMat(A, e), "\n");
Print(SolutionIntMat(A, 2*e) <> fail, "\n");

